<template><main class="search-page"><header><button @click="$router.back()"><van-icon name="arrow-left" /></button><form @submit.prevent="search"><van-icon name="search"/><input v-model="keyword" autofocus placeholder="搜索当前资讯流"/><button>搜索</button></form></header><section><p class="label">SEARCH RESULTS</p><h1>{{ keyword ? `“${keyword}” 的新闻` : '搜索新闻' }}</h1><p class="hint">当前资讯流中包含该关键词的全部结果</p><news-item v-for="(item,i) in results" :key="item.id" :news="item" :index="i"/><div v-if="searched&&!results.length" class="empty">当前资讯流中未找到相关新闻，请换一个关键词。</div></section></main></template>
<script setup>
import { computed, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import NewsItem from '../components/NewsItem.vue'
const route=useRoute();const router=useRouter();const keyword=ref(route.query.q||'');const searched=ref(Boolean(keyword.value));const source=ref(JSON.parse(sessionStorage.getItem('search-source')||sessionStorage.getItem('latest-news')||'[]'))
const normalize=value=>String(value||'').toLocaleLowerCase();const results=computed(()=>{const term=normalize(keyword.value.trim());return term?source.value.filter(item=>normalize(item.title).includes(term)||normalize(item.description).includes(term)):[]})
const search=()=>{const term=keyword.value.trim();if(!term)return;searched.value=true;router.replace({query:{q:term}})}
</script>
<style scoped>.search-page{min-height:100vh;background:radial-gradient(circle at 90% 0,#4d318c,transparent 35%),#090b16;color:#f1f2ff;padding:0 clamp(18px,7vw,150px) 80px}.search-page header{display:flex;gap:14px;align-items:center;padding:24px 0}.search-page header>button{border:0;background:transparent;color:#fff;font-size:22px}.search-page form{display:flex;align-items:center;gap:10px;flex:1;border:1px solid #373957;background:#151726;border-radius:15px;padding:10px 14px}.search-page input{flex:1;border:0;outline:0;background:transparent;color:#fff;font-size:16px}.search-page form button{border:0;background:#7658f8;color:#fff;border-radius:9px;padding:8px 14px}.label{color:#a890ff;font-size:11px;letter-spacing:2px;margin:44px 0 5px}.search-page h1{margin:0;font-size:clamp(26px,4vw,42px)}.hint{color:#959bb5;margin:8px 0 18px}.empty{text-align:center;padding:60px;color:#9ba0bb}</style>
